The `JsonDocument`, in its v1 implementation, is read-only (i.e. it is not modifiable).

One thing you could do as a workaround, via the `Utf8JsonWriter`, is enumerate all the tokens of the `JsonDocument`, and write them out to the writer (including inserting the custom JSON object you have). You can then pass the output of the `Utf8JsonWriter` to `JsonDocument.Parse` to get a `JsonDocument` containing your whole JSON.

Maybe something like this (note: this isn't fully tested, just a sample):
```C#
[Fact]
public static void ModifyJsonDocument()
{
    string originalJson = "{\"hi\": 1}";
    JsonDocument doc = JsonDocument.Parse(originalJson);

    JsonDocument newDoc = AddJsonData(doc, doc);

    Assert.Equal("{\"hi\":1,\"mySubElement\":{\"hi\":1}}", newDoc.RootElement.ToString());
}

private static JsonDocument AddJsonData(JsonDocument original, JsonDocument subOject)
{
    JsonElement element = original.RootElement;
    var abw = new ArrayBufferWriter<byte>();
    using var writer = new Utf8JsonWriter(abw);

    writer.WriteStartObject();
    foreach(JsonProperty properties in element.EnumerateObject())
    {
        properties.Value.WriteProperty(properties.Name, writer);
    }
    JsonElement subElement = subOject.RootElement;
    subElement.WriteProperty("mySubElement", writer);
    writer.WriteEndObject();

    writer.Flush();

    return JsonDocument.Parse(abw.WrittenMemory);
}
```

