> Is there functionality within the CancellationTokenSource class (or elsewhere) that creates a linked token where all of the subject tokens must be cancelled for the derived one to be considered cancelled?

There's nothing built into .NET, but you could easily build your own, e.g. (untested)
```C#
sealed class AllLinkedSource : CancellationTokenSource
{
    private readonly CancellationTokenRegistration[] _registrations;
    private int _remaining;

    public AllLinkedSource(params CancellationToken[] tokens)
    {
        _remaining = tokens.Length;
        _registrations = new CancellationTokenRegistration[tokens.Length];
        for (int i = 0; i < tokens.Length; i++)
        {
            _registrations[i] = tokens[i].Register(t =>
            {
                var thisRef = (AllLinkedSource)t;
                if (Interlocked.Decrement(ref thisRef._remaining) == 0) thisRef.Cancel();
            }, this);
        }
    }

    protected override void Dispose(bool disposing)
    {
        foreach (CancellationTokenRegistration reg in _registrations) reg.Dispose();
        base.Dispose(disposing);
    }
}
```

